def reverse_k_group(songs, k):
    n = len(songs)
    result = list(songs)
    for start in range(0, n, k):
        end = start + k
        if end > n:
            break
        left, right = start, end - 1
        while left < right:
            result[left], result[right] = result[right], result[left]
            left += 1
            right -= 1
    return result
